                retVals[qInd] = values[0];
            }
            return retVals;
        }
        double[] vals = values.clone();
        Arrays.sort(vals);
        double q;
        int ind1, ind2;
        for (int qInd = 0; qInd < qs.length; qInd++) {
            q = qs[qInd];
